window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-99dc75a2b049f0de"]={"versions": [{"id": "FIG-99dc75a2b049f0de", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P11Forward</code> im Rahmen des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm modelliert das Verhalten bei der Weiterleitung bzw. erneuten Absicherung von E2E-geschützten Nutzdaten auf Kommunikations- oder Gateway-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Entry Point</strong>: <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>\n</li><li><strong>Eingangs- / Zustandsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsparameter des E2E-Profils 11\n</li><li><code>State</code>: Dynamischer Zustandsvektor (u. a. interner Zählerstand)\n</li><li><code>Data</code>: Zu schützender Datenpuffer\n</li><li><code>Length</code>: Datenlänge\n</li><li><code>CheckStatus</code>: Status einer vorangegangenen Prüfung\n</li></ul>\n</li><li><strong>Sub-Aktivitäten (Aufrufaktionen)</strong>:\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Write DataIDNibble</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li><strong>Kontrollknoten</strong>:\n<ul class=\"fig-list\"><li>Initialknoten\n</li><li>Verzweigung mit Guards <code>[input ok]</code> und <code>[wrong input]</code>\n</li><li>Drei Aktivitätsendknoten mit Rücksprung (<code>return</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start über Initialknoten bei Aufruf von <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>.\n</li><li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand der Eingangsparameter:\n<ul class=\"fig-list\"><li>Bei fehlerhaften Eingaben (<code>[wrong input]</code>): Verzweigung nach links oder rechts zu einem Aktivitätsendknoten und sofortiges Beenden (<code>return</code>).\n</li><li>Bei gültigen Eingaben (<code>[input ok]</code>): Sequenzielle Ausführung der Profil-11-Schritte:\n a. <code>Write DataIDNibble</code>: Schreiben des Data-ID-Nibbles in den Datenpuffer.\n b. <code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in die Payload.\n c. <code>Compute CRC</code>: Berechnung der CRC über die Daten inklusive Data-ID.\n d. <code>Write CRC</code>: Eintragen der berechneten CRC in den Datenpuffer.\n e. <code>Increment Counter</code>: Inkrementieren des Zählers für die nachfolgende Übertragung.\n</li></ul>\n</li><li>Reguläres Beenden der Funktion über den zentralen Aktivitätsendknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindlicher Kontrollfluss für die Implementierung der Funktion <code>E2E_P11Forward</code>.\n</li><li>Eingangsvalidierung (<code>Verify inputs of the protect function</code>) ist zwingend vor jeglicher Datenmodifikation durchzuführen; bei ungültigen Eingaben darf keine Veränderung des Puffers (<code>Data</code>) oder Zählerstands (<code>State</code>) erfolgen.\n</li><li>Die Schritte <code>Write DataIDNibble</code> und <code>Write Counter</code> müssen vor <code>Compute CRC</code> ausgeführt werden, da beide Werte in die CRC-Berechnung einfließen.\n</li><li><code>Increment Counter</code> darf erst nach erfolgreicher CRC-Erzeugung und Pufferbeschriftung erfolgen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c1e7f71d05f5548e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P11Forward</code> im Rahmen des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm modelliert das Verhalten bei der Weiterleitung bzw. erneuten Absicherung von E2E-geschützten Nutzdaten auf Kommunikations- oder Gateway-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Entry Point</strong>: <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>\n</li><li><strong>Eingangs- / Zustandsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsparameter des E2E-Profils 11\n</li><li><code>State</code>: Dynamischer Zustandsvektor (u. a. interner Zählerstand)\n</li><li><code>Data</code>: Zu schützender Datenpuffer\n</li><li><code>Length</code>: Datenlänge\n</li><li><code>CheckStatus</code>: Status einer vorangegangenen Prüfung\n</li></ul>\n</li><li><strong>Sub-Aktivitäten (Aufrufaktionen)</strong>:\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Write DataIDNibble</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li><strong>Kontrollknoten</strong>:\n<ul class=\"fig-list\"><li>Initialknoten\n</li><li>Verzweigung mit Guards <code>[input ok]</code> und <code>[wrong input]</code>\n</li><li>Drei Aktivitätsendknoten mit Rücksprung (<code>return</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start über Initialknoten bei Aufruf von <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>.\n</li><li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand der Eingangsparameter:\n<ul class=\"fig-list\"><li>Bei fehlerhaften Eingaben (<code>[wrong input]</code>): Verzweigung nach links oder rechts zu einem Aktivitätsendknoten und sofortiges Beenden (<code>return</code>).\n</li><li>Bei gültigen Eingaben (<code>[input ok]</code>): Sequenzielle Ausführung der Profil-11-Schritte:\n a. <code>Write DataIDNibble</code>: Schreiben des Data-ID-Nibbles in den Datenpuffer.\n b. <code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in die Payload.\n c. <code>Compute CRC</code>: Berechnung der CRC über die Daten inklusive Data-ID.\n d. <code>Write CRC</code>: Eintragen der berechneten CRC in den Datenpuffer.\n e. <code>Increment Counter</code>: Inkrementieren des Zählers für die nachfolgende Übertragung.\n</li></ul>\n</li><li>Reguläres Beenden der Funktion über den zentralen Aktivitätsendknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindlicher Kontrollfluss für die Implementierung der Funktion <code>E2E_P11Forward</code>.\n</li><li>Eingangsvalidierung (<code>Verify inputs of the protect function</code>) ist zwingend vor jeglicher Datenmodifikation durchzuführen; bei ungültigen Eingaben darf keine Veränderung des Puffers (<code>Data</code>) oder Zählerstands (<code>State</code>) erfolgen.\n</li><li>Die Schritte <code>Write DataIDNibble</code> und <code>Write Counter</code> müssen vor <code>Compute CRC</code> ausgeführt werden, da beide Werte in die CRC-Berechnung einfließen.\n</li><li><code>Increment Counter</code> darf erst nach erfolgreicher CRC-Erzeugung und Pufferbeschriftung erfolgen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-99dc75a2b049f0de", "to": "FIG-c1e7f71d05f5548e", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
